<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import ExperimentSupport from '@/components/ExperimentSupport.vue'
import MathFormula from '@/components/MathFormula.vue'
import {useLevel} from '@/composables/useLevel'
import {snapToRange,useQuerySync} from '@/composables/useQuerySync'
import {useLocale} from '@/composables/useLocale'
import {atLeast,isLevel} from '@/levels'
import {calculateMomentumCollision} from '@/physics'
import {experimentSectionLabel,getExperimentModuleEyebrow} from '@/i18n/experiment-metadata'
import {getMomentumCollisionsDocumentTitle,localizeMomentumCollisionsText} from './copy'
const route=useRoute(),level=useLevel(),{locale}=useLocale(),tx=(s:string)=>localizeMomentumCollisionsText(s,locale.value)
const mass1=ref(snapToRange(route.query.m1,{min:1,max:10,step:.5},2)),mass2=ref(snapToRange(route.query.m2,{min:1,max:10,step:.5},2))
const velocity1=ref(snapToRange(route.query.v1,{min:-8,max:8,step:.5},4)),velocity2=ref(snapToRange(route.query.v2,{min:-8,max:8,step:.5},0))
const restitution=ref(snapToRange(route.query.e,{min:0,max:1,step:.05},1))
if(isLevel(route.query.level))level.value=route.query.level
useQuerySync({sources:[mass1,mass2,velocity1,velocity2,restitution,level],write:()=>({level:level.value,m1:String(mass1.value),m2:String(mass2.value),v1:String(velocity1.value),v2:String(velocity2.value),e:restitution.value.toFixed(2)}),read:q=>{if(isLevel(q.level))level.value=q.level;mass1.value=snapToRange(q.m1,{min:1,max:10,step:.5},mass1.value);mass2.value=snapToRange(q.m2,{min:1,max:10,step:.5},mass2.value);velocity1.value=snapToRange(q.v1,{min:-8,max:8,step:.5},velocity1.value);velocity2.value=snapToRange(q.v2,{min:-8,max:8,step:.5},velocity2.value);restitution.value=snapToRange(q.e,{min:0,max:1,step:.05},restitution.value)}})
const prediction=ref<'cart1'|'cart2'|'together'|null>(null),tested=ref(false)
const result=computed(()=>calculateMomentumCollision({mass1:mass1.value,mass2:mass2.value,velocity1:velocity1.value,velocity2:velocity2.value,restitution:restitution.value}))
const expected=computed(()=>Math.abs(result.value.velocity1After-result.value.velocity2After)<1e-8?'together':Math.abs(result.value.velocity1After)>=Math.abs(result.value.velocity2After)?'cart1':'cart2')
const matches=computed(()=>prediction.value===expected.value),isApproaching=computed(()=>velocity1.value>velocity2.value),intermediate=computed(()=>atLeast(level.value,'intermediate')),advanced=computed(()=>atLeast(level.value,'advanced'))
const fmt=(n:number,d=2)=>Number(n.toFixed(d)).toString(),lossPct=computed(()=>result.value.kineticEnergyBefore>0?100*result.value.kineticEnergyLost/result.value.kineticEnergyBefore:0)
watch([mass1,mass2,velocity1,velocity2,restitution],()=>{prediction.value=null;tested.value=false})
watch(locale,()=>{if(route.name==='momentum-collisions')document.title=getMomentumCollisionsDocumentTitle(locale.value)})
</script>
<template><article class="lesson container momentum-collisions">
<header class="lesson-head"><p class="eyebrow">{{getExperimentModuleEyebrow('momentum-collisions',locale)}}</p><h1>{{tx('Momentum and collisions')}}</h1><p class="lead">{{tx('Two carts approach, collide and move apart. Predict their motion first, then investigate what momentum conservation tells us—and what it does not tell us about kinetic energy.')}}</p></header>
<section><h2><span class="step-no">1</span> {{experimentSectionLabel('predict',locale)}}</h2><div class="card prediction"><p>{{tx('Before the collision, which cart will move faster afterward?')}}</p><fieldset><legend>{{tx('Your prediction')}}</legend><label><input v-model="prediction" type="radio" name="collision-prediction" value="cart1">{{tx('Cart 1 moves faster')}}</label><label><input v-model="prediction" type="radio" name="collision-prediction" value="cart2">{{tx('Cart 2 moves faster')}}</label><label><input v-model="prediction" type="radio" name="collision-prediction" value="together">{{tx('They move together')}}</label></fieldset><p v-if="tested" class="verdict" role="status">{{matches?tx('Your prediction matches the model.'):tx('Compare the final velocities with your prediction.')}}</p></div></section>
<section><h2><span class="step-no">2</span> {{experimentSectionLabel('experiment',locale)}}</h2><div class="card controls"><div class="control-grid">
<label>{{tx('Cart 1 mass')}} <output>{{fmt(mass1)}} kg</output><input v-model.number="mass1" type="range" min="1" max="10" step=".5"></label><label>{{tx('Cart 2 mass')}} <output>{{fmt(mass2)}} kg</output><input v-model.number="mass2" type="range" min="1" max="10" step=".5"></label>
<label>{{tx('Cart 1 initial velocity')}} <output>{{fmt(velocity1)}} m/s</output><input v-model.number="velocity1" type="range" min="-8" max="8" step=".5"></label><label>{{tx('Cart 2 initial velocity')}} <output>{{fmt(velocity2)}} m/s</output><input v-model.number="velocity2" type="range" min="-8" max="8" step=".5"></label>
<label class="wide">{{tx('Coefficient of restitution')}} <output>{{fmt(restitution,2)}} · {{tx(restitution===1?'Elastic':restitution===0?'Perfectly inelastic':'Inelastic')}}</output><input v-model.number="restitution" type="range" min="0" max="1" step=".05"></label>
</div><p class="muted">{{tx('The coefficient of restitution compares separation speed with approach speed along the collision line.')}}</p><p v-if="!isApproaching" class="verdict" role="status">{{tx('Cart 1 must be moving faster than cart 2 for these carts to collide.')}}</p>
<div class="cart-scene"><div><strong>{{tx('Initial')}}</strong><span>1: {{fmt(velocity1)}} m/s</span><span>2: {{fmt(velocity2)}} m/s</span></div><div><strong>{{tx('Final')}}</strong><span>1: {{fmt(result.velocity1After)}} m/s</span><span>2: {{fmt(result.velocity2After)}} m/s</span></div></div>
<button class="button button-primary" type="button"  :disabled="!prediction || !isApproaching" @click="tested=true">{{tx('Run collision')}}</button><p v-if="tested" class="muted" role="status">{{tx('Momentum is conserved in this model; kinetic energy is conserved only when the collision is elastic.')}}</p></div>
<div class="card results"><h3>{{tx('Final')}} · {{tx('Velocity')}}</h3><div class="result-grid">
<div><span>v₁′</span><strong>{{fmt(result.velocity1After)}} m/s</strong></div><div><span>v₂′</span><strong>{{fmt(result.velocity2After)}} m/s</strong></div><div><span>{{tx('Momentum before')}}</span><strong>{{fmt(result.momentumBefore)}} kg·m/s</strong></div><div><span>{{tx('Momentum after')}}</span><strong>{{fmt(result.momentumAfter)}} kg·m/s</strong></div>
<div><span>{{tx('Kinetic energy before')}}</span><strong>{{fmt(result.kineticEnergyBefore)}} J</strong></div><div><span>{{tx('Kinetic energy after')}}</span><strong>{{fmt(result.kineticEnergyAfter)}} J</strong></div><div><span>{{tx('Kinetic energy lost')}}</span><strong>{{fmt(result.kineticEnergyLost)}} J ({{fmt(lossPct,1)}}%)</strong></div><div><span>{{tx('Momentum change')}}</span><strong>{{fmt(result.momentumChange,5)}} kg·m/s</strong></div><div><span>{{tx('Impulse on cart 1')}}</span><strong>{{fmt(result.impulseOn1)}} N·s</strong></div><div><span>{{tx('Impulse on cart 2')}}</span><strong>{{fmt(result.impulseOn2)}} N·s</strong></div>
</div></div></section>
<section><h2><span class="step-no">3</span> {{experimentSectionLabel('mathematics',locale)}}</h2><div class="card math-content">
<p>{{tx('Beginner: momentum is mass multiplied by velocity. In an isolated collision, the total momentum before and after is the same. Kinetic energy may decrease in an inelastic collision.')}}</p>
<template v-if="intermediate"><p>{{tx('Intermediate: use conservation of momentum together with the coefficient of restitution e, the ratio of relative separation speed to relative approach speed. e = 1 is elastic; e = 0 is perfectly inelastic.')}}</p><MathFormula tex="m_1u_1+m_2u_2=m_1v_1+m_2v_2"/><MathFormula tex="v_2-v_1=e(u_1-u_2)"/></template>
<template v-if="advanced"><p>{{tx('Advanced: the center-of-mass velocity is constant. The impulse on one cart is equal and opposite to the impulse on the other. For this isolated two-body model, kinetic-energy loss is one half of the reduced mass times (1 − e²) times the squared initial relative speed.')}}</p><MathFormula tex="V_{CM}=\frac{m_1u_1+m_2u_2}{m_1+m_2}"/><MathFormula tex="\Delta K=-\frac12\mu(1-e^2)(u_1-u_2)^2,\quad \mu=\frac{m_1m_2}{m_1+m_2}"/></template>
<p>{{tx('Momentum is conserved in this model; kinetic energy is conserved only when the collision is elastic.')}}</p></div></section>
<section class="card"><h2>{{tx('Model assumptions and limits')}}</h2><p>{{tx('This is a one-dimensional, isolated, two-body collision. External impulse during impact is neglected; masses remain constant; the coefficient of restitution is constant and lies between zero and one. Rotation, deformation details, sound, heat, fragmentation and multidimensional contact are not simulated. Kinetic energy not retained as translational kinetic energy is transferred to internal energy, sound or deformation; it is not destroyed.')}}</p></section>
<ExperimentSupport experiment-id="momentum-collisions" :module-number="3" focus="Momentum is conserved in an isolated collision, but kinetic energy depends on the collision's elasticity." prompt="Before running the collision, predict the final directions and speeds of both carts." action="Change one mass, initial velocity or restitution value at a time; compare momentum and kinetic energy before and after." reflect="If momentum is unchanged but kinetic energy decreases, where might the energy have gone?"/>
<nav class="experiment-footer"><RouterLink to="/mechanics/force-lab">{{tx('← Force Lab')}}</RouterLink><RouterLink to="/">{{tx('All modules')}}</RouterLink></nav>
</article></template>
<style scoped>
.momentum-collisions{display:grid;gap:28px}.momentum-collisions section{display:grid;gap:14px}.prediction,.controls,.results,.math-content{display:grid;gap:16px}.prediction fieldset{display:flex;flex-wrap:wrap;gap:14px;border:0;padding:0}.prediction label{display:flex;align-items:center;gap:8px}.control-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:18px}.control-grid label{display:grid;gap:8px;font-weight:600}.control-grid output{font-weight:500;color:var(--accent)}.control-grid input{width:100%;accent-color:var(--accent)}.wide{grid-column:1/-1}.cart-scene{display:grid;gap:10px;padding:14px;border-radius:12px;background:var(--surface-2)}.cart-scene>div{display:grid;grid-template-columns:90px repeat(2,minmax(0,1fr));gap:10px;font-variant-numeric:tabular-nums}.result-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,190px),1fr));gap:12px}.result-grid>div{display:grid;gap:4px;padding:12px;border:1px solid var(--border);border-radius:10px}.result-grid span{color:var(--text-muted);font-size:.86rem}.result-grid strong{font-variant-numeric:tabular-nums}.verdict{font-weight:650;color:var(--accent)}.experiment-footer{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}@media(max-width:520px){.cart-scene>div{grid-template-columns:1fr;gap:4px}}
</style>